import type { ReactNode } from "react";
import {
  Body,
  Button,
  type ButtonProps,
  Container,
  Head,
  Heading,
  type HeadingProps,
  Html,
  Link,
  type LinkProps,
  Preview,
  pixelBasedPreset,
  Tailwind,
  type TailwindConfig,
  Text,
  type TextProps,
} from "react-email";
import type { EmailTheme } from "./theme";

function tailwindTheme(theme: EmailTheme): TailwindConfig {
  return {
    presets: [pixelBasedPreset],
    theme: {
      extend: {
        colors: theme.colors,
        borderRadius: theme.radii,
        minHeight: { control: theme.button.height },
        padding: { "control-x": theme.button.paddingInline, "control-y": theme.button.paddingBlock },
        fontFamily: { body: theme.fonts.body, display: theme.fonts.display },
        fontSize: {
          ...Object.fromEntries(Object.entries(theme.text).map(([name, { fontSize, ...options }]) => [name, [fontSize, options]])),
          control: [theme.button.fontSize, { lineHeight: theme.button.lineHeight }],
        },
      },
    },
  };
}

export function EmailLayout({
  theme,
  preview,
  children,
  head,
  lang = "en",
  dir = "ltr",
}: {
  theme: EmailTheme;
  preview: string;
  children: ReactNode;
  head?: ReactNode;
  lang?: string;
  dir?: "ltr" | "rtl";
}) {
  return (
    <Html lang={lang} dir={dir}>
      <Tailwind config={tailwindTheme(theme)}>
        <Head>{head}</Head>
        <Body className="m-0 bg-background p-4 font-body text-body text-foreground">
          <Preview>{preview}</Preview>
          <Container className="mx-auto w-full max-w-[600px] rounded-panel bg-card p-6 text-card-foreground">{children}</Container>
        </Body>
      </Tailwind>
    </Html>
  );
}

const headingClasses = { h1: "text-heading-1", h2: "text-heading-2", h3: "text-heading-3", h4: "text-heading-4" };

export function EmailHeading({ as = "h1", className = "", ...props }: Omit<HeadingProps, "as"> & { as?: keyof typeof headingClasses }) {
  return <Heading {...props} as={as} className={`mb-4 mt-0 font-display text-card-foreground ${headingClasses[as]} ${className}`} />;
}

export function EmailText({ tone = "default", className = "", style, ...props }: TextProps & { tone?: "default" | "muted" }) {
  const textColor = tone === "muted" ? "text-muted-foreground" : "text-card-foreground";
  return (
    <Text
      {...props}
      style={{ overflowWrap: "break-word", ...style }}
      className={`mb-4 mt-0 font-body text-body ${textColor} ${className}`}
    />
  );
}

export function EmailButton({ className = "", ...props }: ButtonProps) {
  return (
    <Button
      {...props}
      className={`box-border min-h-control rounded-control bg-primary px-control-x py-control-y text-center font-body text-control font-medium text-primary-foreground no-underline ${className}`}
    />
  );
}

export function EmailLink({ className = "", ...props }: LinkProps) {
  return <Link {...props} className={`font-body text-primary-text underline ${className}`} />;
}

function parseLengthQuantity(value: string, rootFontSize: number) {
  const match = /^(-?\d*\.?\d+)(px|rem)?$/.exec(value.trim());
  if (!match) return null;
  return { amount: Number(match[1]) * (match[2] === "rem" ? rootFontSize : 1), unit: match[2] ? "px" : "" };
}

function calculateLengthExpression(expression: string, rootFontSize: number) {
  const match = /^\s*(-?\d*\.?\d+(?:px|rem)?)\s*([+*/-])\s*(-?\d*\.?\d+(?:px|rem)?)\s*$/.exec(expression);
  if (!match) return null;
  const left = parseLengthQuantity(match[1], rootFontSize);
  const right = parseLengthQuantity(match[3], rootFontSize);
  if (!left || !right) return null;
  const operator = match[2];
  if ((operator === "+" || operator === "-") && left.unit === right.unit) {
    return `${left.amount + (operator === "+" ? right.amount : -right.amount)}${left.unit}`;
  }
  if (operator === "*" && !(left.unit && right.unit)) return `${left.amount * right.amount}${left.unit || right.unit}`;
  const dividesByScalar = operator === "/" && !right.unit && right.amount !== 0;
  if (dividesByScalar) return `${left.amount / right.amount}${left.unit}`;
  return null;
}

export function emailLengthPixels(name: string, value: string, rootFontSize: number, allowZero = false): number {
  let resolved = value;
  for (let depth = 0; depth < 16 && resolved.includes("calc("); depth++) {
    const simplified = resolved.replace(
      /calc\(([^()]*)\)/g,
      (original, expression: string) => calculateLengthExpression(expression, rootFontSize) ?? original,
    );
    if (simplified === resolved) break;
    resolved = simplified;
  }
  const result = parseLengthQuantity(resolved, rootFontSize);
  const isLength = result && (result.unit === "px" || result.amount === 0);
  const isValidLength = isLength && Number.isFinite(result.amount) && (allowZero ? result.amount >= 0 : result.amount > 0);
  if (!isValidLength) {
    throw new Error(`Email theme: ${name} must resolve to a ${allowZero ? "non-negative" : "positive"} px/rem length, received ${value}.`);
  }
  return result.amount;
}

import { Column, Hr, Img, Row, Section } from "react-email";
import { EmailButton, EmailHeading, EmailLayout, EmailLink, EmailText } from "./email";
import type { EmailTheme } from "./theme";

type EmailBrandProps = { theme: EmailTheme; brand: string; footer: string };

function EmailFooter({ brand, children }: { brand: string; children: string }) {
  return (
    <>
      <Hr className="my-6 border-0 border-t border-solid border-t-border" />
      <EmailText tone="muted" className="mb-1 text-caption">
        {brand}
      </EmailText>
      <EmailText tone="muted" className="mb-0 text-caption">
        {children}
      </EmailText>
    </>
  );
}

export function InvitationEmail({
  theme,
  brand,
  footer,
  inviter,
  workspace,
  inviteUrl,
}: EmailBrandProps & {
  inviter: string;
  workspace: string;
  inviteUrl: string;
}) {
  return (
    <EmailLayout theme={theme} preview={`${inviter} invited you to ${workspace}`}>
      <EmailText tone="muted" className="mb-8 text-caption">
        {brand}
      </EmailText>
      <EmailHeading>A place for your next idea.</EmailHeading>
      <EmailText>
        {inviter} invited you to join <strong>{workspace}</strong>. Bring your work, share a little inspiration, and make something
        together.
      </EmailText>
      <Section className="my-6 rounded-panel bg-muted p-5">
        <EmailHeading as="h3">Your team is waiting</EmailHeading>
        <EmailText className="mb-0">Projects, conversations, and the details that move work forward. All in one shared space.</EmailText>
      </Section>
      <EmailButton href={inviteUrl}>Join {workspace}</EmailButton>
      <EmailFooter brand={brand}>{footer}</EmailFooter>
    </EmailLayout>
  );
}

export function ProductEmail({
  theme,
  brand,
  footer,
  title,
  description,
  imageUrl,
  imageAlt,
  actionUrl,
}: EmailBrandProps & {
  title: string;
  description: string;
  imageUrl: string;
  imageAlt: string;
  actionUrl: string;
}) {
  return (
    <EmailLayout theme={theme} preview={title}>
      <EmailText tone="muted" className="mb-6 text-caption">
        {brand} / NEW RELEASE
      </EmailText>
      <Img src={imageUrl} alt={imageAlt} width="552" className="mb-6 block h-auto w-full rounded-scene" />
      <EmailHeading>{title}</EmailHeading>
      <EmailText>{description}</EmailText>
      <EmailButton href={actionUrl}>Explore what’s new</EmailButton>
      <EmailFooter brand={brand}>{footer}</EmailFooter>
    </EmailLayout>
  );
}

export function EditorialEmail({
  theme,
  brand,
  footer,
  title,
  description,
  imageUrl,
  imageAlt,
  articleUrl,
}: EmailBrandProps & {
  title: string;
  description: string;
  imageUrl: string;
  imageAlt: string;
  articleUrl: string;
}) {
  return (
    <EmailLayout theme={theme} preview={title}>
      <EmailText tone="muted" className="mb-6 text-caption">
        {brand} / IN GOOD COMPANY
      </EmailText>
      <EmailHeading>Fresh perspectives.</EmailHeading>
      <Row>
        <Column width="36%" className="align-top">
          <Img src={imageUrl} alt={imageAlt} width="198" className="block h-auto w-full rounded-scene" />
        </Column>
        <Column width="64%" className="pl-5 align-top">
          <EmailHeading as="h2">{title}</EmailHeading>
          <EmailText>{description}</EmailText>
          <EmailLink href={articleUrl}>Read the story</EmailLink>
        </Column>
      </Row>
      <EmailFooter brand={brand}>{footer}</EmailFooter>
    </EmailLayout>
  );
}

export type EmailArticle = { title: string; description: string; href: string; imageUrl: string; imageAlt: string };

export function NewsletterEmail({
  theme,
  brand,
  footer,
  articles,
  unsubscribeUrl,
}: EmailBrandProps & {
  articles: EmailArticle[];
  unsubscribeUrl: string;
}) {
  return (
    <EmailLayout theme={theme} preview="A few things worth making time for.">
      <EmailText tone="muted" className="mb-6 text-caption">
        {brand} / THE WEEKLY EDIT
      </EmailText>
      <EmailHeading>A little room for inspiration.</EmailHeading>
      <EmailText tone="muted">A few things worth making time for. Stories, spaces, and ideas from our community.</EmailText>
      {articles.map((article) => (
        <Section key={article.href} className="mb-6">
          <Img src={article.imageUrl} alt={article.imageAlt} width="552" className="mb-4 block h-auto w-full rounded-scene" />
          <EmailHeading as="h2">{article.title}</EmailHeading>
          <EmailText>{article.description}</EmailText>
          <EmailLink href={article.href}>Read the story</EmailLink>
        </Section>
      ))}
      <EmailFooter brand={brand}>{footer}</EmailFooter>
      <EmailLink href={unsubscribeUrl} className="text-caption">
        Unsubscribe
      </EmailLink>
    </EmailLayout>
  );
}

export function SummaryEmail({
  theme,
  brand,
  footer,
  period,
  metrics,
  details,
  dashboardUrl,
}: EmailBrandProps & {
  period: string;
  metrics: { label: string; value: string }[];
  details: { label: string; value: string }[];
  dashboardUrl: string;
}) {
  return (
    <EmailLayout theme={theme} preview={`Your team’s progress · ${period}`}>
      <EmailText tone="muted" className="mb-6 text-caption">
        {brand} / {period}
      </EmailText>
      <EmailHeading>Good work adds up.</EmailHeading>
      <EmailText>Here’s what your team moved forward this week.</EmailText>
      <Section className="my-6 rounded-panel bg-muted p-4">
        <Row className="table-fixed">
          {metrics.map((metric) => (
            <Column key={metric.label} className="px-2 align-top">
              <EmailText className="mb-1 text-heading-2 font-semibold">{metric.value}</EmailText>
              <EmailText tone="muted" className="mb-0 text-caption">
                {metric.label}
              </EmailText>
            </Column>
          ))}
        </Row>
      </Section>
      {details.map((detail) => (
        <Row key={detail.label} className="table-fixed">
          <Column>
            <EmailText>{detail.label}</EmailText>
          </Column>
          <Column align="right">
            <EmailText>{detail.value}</EmailText>
          </Column>
        </Row>
      ))}
      <EmailButton href={dashboardUrl}>View your workspace</EmailButton>
      <EmailFooter brand={brand}>{footer}</EmailFooter>
    </EmailLayout>
  );
}

import { composite, resolveColor, tokenMaps } from "../scripts/contrast-eval.mjs";
import { emailLengthPixels } from "./length";

const emailColors = [
  "background",
  "foreground",
  "card",
  "card-foreground",
  "primary",
  "primary-foreground",
  "primary-text",
  "muted",
  "muted-foreground",
  "border",
] as const;
const headingSizes = ["heading-1", "heading-2", "heading-3", "heading-4"] as const;

type EmailColor = (typeof emailColors)[number];
type EmailHeadingSize = (typeof headingSizes)[number];
type EmailTypeStyle = { fontSize: string; lineHeight: string; fontWeight: string; letterSpacing: string };

export type EmailTheme = {
  colors: Record<EmailColor, string>;
  fonts: { body: string; display: string };
  radii: { control: string; panel: string; scene: string };
  button: { height: string; paddingInline: string; paddingBlock: string; fontSize: string; lineHeight: string };
  text: Record<EmailHeadingSize | "body" | "caption", EmailTypeStyle>;
};

function resolveVariables(value: string, tokens: ReadonlyMap<string, string>, chain: string[] = []): string {
  if (chain.length > 16) throw new Error(`Email theme: token chain exceeds 16 references (${chain.join(" → ")}).`);
  return value.replace(/var\(\s*(--[\w-]+)\s*(?:,\s*((?:[^()]|\([^()]*\))*))?\)/g, (_, name: string, fallback: string | undefined) => {
    if (chain.includes(name)) throw new Error(`Email theme: circular reference to ${name}.`);
    const resolved = tokens.get(name) ?? fallback;
    if (resolved === undefined) throw new Error(`Email theme: missing ${name}.`);
    return resolveVariables(resolved, tokens, [...chain, name]);
  });
}

function tokenValue(name: string, tokens: ReadonlyMap<string, string>, fallback?: string) {
  const value = tokens.get(name) ?? fallback;
  if (value === undefined) throw new Error(`Email theme: missing ${name}. Include core theme.css before the skin theme.`);
  const resolved = resolveVariables(value, tokens, [name]).trim();
  if (!resolved || /var\(|[;{}<>]/.test(resolved)) throw new Error(`Email theme: unsupported ${name}: ${value}.`);
  return resolved;
}

function pixelSize(name: string, tokens: ReadonlyMap<string, string>, rootFontSize: number) {
  return `${emailLengthPixels(name, tokenValue(name, tokens), rootFontSize)}px`;
}

function numericStyle(name: string, tokens: ReadonlyMap<string, string>, fallback: string) {
  const value = tokenValue(name, tokens, fallback);
  if (!/^\d*\.?\d+(px|em)?$/.test(value)) throw new Error(`Email theme: unsupported ${name}: ${value}.`);
  return value;
}

export function createEmailTheme(tokens: ReadonlyMap<string, string>, rootFontSize = 16): EmailTheme {
  if (!Number.isFinite(rootFontSize) || rootFontSize <= 0) throw new Error("Email theme: rootFontSize must be a positive pixel value.");

  function lengthPixels(name: string, allowZero = false) {
    return emailLengthPixels(name, tokenValue(name, tokens), rootFontSize, allowZero);
  }

  const buttonHeight = lengthPixels("--control-h-md");
  const buttonFontSize = lengthPixels("--text-body");
  const reactEmailButtonLineHeight = buttonFontSize * 1.2;
  const buttonPaddingBlock = Math.max(0, (buttonHeight - reactEmailButtonLineHeight) / 2);

  function color(name: EmailColor) {
    const result = resolveColor(`var(--${name})`, tokens);
    if ("unresolved" in result) throw new Error(`Email theme: --${name}: ${result.unresolved}.`);
    return result;
  }

  const background = color("background");
  if (background.alpha !== 1) throw new Error("Email theme: --background must be opaque.");
  const card = composite(color("card"), background);
  const primary = composite(color("primary"), card);
  function opaqueColor(name: EmailColor, surface = card) {
    const result = composite(color(name), surface);
    return `rgb(${Math.round(result.r)}, ${Math.round(result.g)}, ${Math.round(result.b)})`;
  }

  function heading(name: EmailHeadingSize): EmailTypeStyle {
    const spacing = tokenValue(`--text-${name}--letter-spacing`, tokens, "0");
    if (!/^-?\d*\.?\d+(px|em)?$/.test(spacing)) throw new Error(`Email theme: unsupported ${name} letter spacing: ${spacing}.`);
    return {
      fontSize: pixelSize(`--text-${name}`, tokens, rootFontSize),
      lineHeight: numericStyle(`--text-${name}--line-height`, tokens, "1.3"),
      fontWeight: numericStyle(`--text-${name}--font-weight`, tokens, "600"),
      letterSpacing: spacing,
    };
  }

  return {
    colors: {
      background: opaqueColor("background", background),
      foreground: opaqueColor("foreground", background),
      card: opaqueColor("card", background),
      "card-foreground": opaqueColor("card-foreground"),
      primary: opaqueColor("primary"),
      "primary-foreground": opaqueColor("primary-foreground", primary),
      "primary-text": opaqueColor("primary-text"),
      muted: opaqueColor("muted"),
      "muted-foreground": opaqueColor("muted-foreground"),
      border: opaqueColor("border"),
    },
    fonts: { body: tokenValue("--font-body", tokens), display: tokenValue("--font-display", tokens) },
    radii: {
      control: `${lengthPixels("--radius-control", true)}px`,
      panel: `${lengthPixels("--radius-panel", true)}px`,
      scene: `${lengthPixels("--radius-scene", true)}px`,
    },
    button: {
      height: `${buttonHeight}px`,
      paddingInline: `${lengthPixels("--padding-x", true)}px`,
      paddingBlock: `${buttonPaddingBlock}px`,
      fontSize: `${buttonFontSize}px`,
      lineHeight: `${reactEmailButtonLineHeight}px`,
    },
    text: {
      body: { fontSize: pixelSize("--text-body-lg", tokens, rootFontSize), lineHeight: "1.6", fontWeight: "400", letterSpacing: "0" },
      caption: { fontSize: pixelSize("--text-body", tokens, rootFontSize), lineHeight: "1.5", fontWeight: "400", letterSpacing: "0" },
      "heading-1": heading("heading-1"),
      "heading-2": heading("heading-2"),
      "heading-3": heading("heading-3"),
      "heading-4": heading("heading-4"),
    },
  };
}

export function emailThemeFromCss(cssSources: string[], mode: "light" | "dark" = "light", rootFontSize = 16): EmailTheme {
  return createEmailTheme(tokenMaps(cssSources)[mode], rootFontSize);
}
